package gateway

import "html/template"

var page = template.Must(template.New("page").Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>mcp-gateway · Activity</title><style>
:root{font-family:system-ui,sans-serif;color:#172b26;background:#f6f7f3}*{box-sizing:border-box}body{margin:0}header{background:#153e32;color:#fff;padding:22px max(24px,calc((100vw - 1100px)/2));display:flex;align-items:center;justify-content:space-between;gap:16px}header a{color:white;text-decoration:none;font-size:20px;font-weight:750}header small{color:#c3d7cc}main{max-width:1100px;margin:40px auto;padding:0 24px 60px}h1{font-size:32px;letter-spacing:-1px;margin-bottom:8px}h2{font-size:20px;margin-top:32px}.sub{color:#586b62;margin-top:0;line-height:1.6}.card{background:white;border:1px solid #dbe1d9;border-radius:12px;padding:24px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.grid .card{margin:0}a{color:#226a4d}button,.button{display:inline-block;border:1px solid #bccdc0;border-radius:6px;padding:10px 16px;background:white;color:#234b37;font:inherit;cursor:pointer;text-decoration:none}.primary{background:#216442;color:white;border-color:#216442}.danger{color:#9f3535}.actions{display:flex;gap:12px;margin-top:20px}form{margin:0}.badge{font:12px ui-monospace,monospace;border-radius:5px;padding:5px 8px;background:#eaf0e8;display:inline-block}.pending{background:#fff0c6;color:#77550b}.unknown,.denied,.failed{background:#fde9e5;color:#9c3724}.succeeded{background:#dff3e5;color:#175e37}table{border-collapse:collapse;width:100%;text-align:left;font-size:14px}td,th{padding:14px 10px;border-bottom:1px solid #e7ebe5}th{font-weight:500;color:#66756d;font-size:12px;text-transform:uppercase}code,pre{font-family:ui-monospace,monospace;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f5ef;padding:20px;border-radius:8px}dl{display:grid;grid-template-columns:150px 1fr;gap:14px}dt{color:#647267}dd{margin:0;overflow-wrap:anywhere}.scroll{overflow-x:auto}.note{border-left:3px solid #d4a740;padding:12px 16px;background:#fff9e9;font-size:14px;line-height:1.6}footer{font-size:12px;color:#6d786d;margin-top:32px}@media(max-width:600px){header{flex-wrap:wrap}main{margin-top:24px}.card{padding:16px}dl{grid-template-columns:1fr;gap:6px}dd{margin-bottom:10px}h1{font-size:27px}}
</style><style>
.heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.setup{max-width:760px;margin:auto}.field{display:grid;gap:8px;margin-bottom:22px}.field label{font-weight:600}.field small,.help{color:#586b62;line-height:1.5}input,select{box-sizing:border-box;width:100%;padding:11px 12px;border:1px solid #bccdc0;border-radius:6px;background:white;color:#172b26;font:inherit}input:focus,select:focus{outline:2px solid #216442;outline-offset:2px}.setup details{margin:16px 0}.setup summary,summary{cursor:pointer}.setup details .field{margin-top:18px}.error{background:#fde9e5;border-left:3px solid #9f3535;padding:16px}.success{background:#dff3e5;padding:16px}.setup form:not(:has(option[value="bearer"]:checked)) .bearer-fields{display:none}.setup form:not(:has(option[value="oauth"]:checked)) .oauth-fields{display:none}.tool-row{display:grid;grid-template-columns:minmax(0,1fr) 210px;gap:24px;padding:22px 0;border-bottom:1px solid #e7ebe5}.tool-row:last-child{border:0}.tool-row h2{margin:0 0 8px;font:600 16px ui-monospace,monospace;overflow-wrap:anywhere}.tool-row p{line-height:1.5;overflow-wrap:anywhere}.tool-row details{margin-top:12px}.tool-row label{display:block;font-size:13px;margin-bottom:8px}.actions{flex-wrap:wrap}.endpoint{overflow-wrap:anywhere} @media(max-width:600px){.tool-row{grid-template-columns:1fr;gap:8px}.heading{align-items:flex-start;flex-direction:column}}
@media(min-width:601px){.tool-row{grid-template-columns:minmax(0,1fr) 260px}}
.permissions{max-width:820px;margin:auto}.connection-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:18px 0 6px}.connection-heading h1{margin:0;font-size:28px;overflow-wrap:anywhere}.auth-status{flex-shrink:0;font-size:13px;list-style:none;border:1px solid #bccdc0;border-radius:6px;padding:8px 12px;cursor:pointer;color:#226a4d}.auth-status::-webkit-details-marker{display:none}.auth-status:before{content:'●';margin-right:8px}.auth-status.pending{color:#77550b}.auth-details{max-width:440px}.auth-details[open]{align-self:flex-start}.auth-details .help{font-size:13px}.auth-details summary:focus-visible,button:focus-visible,.button:focus-visible{outline:2px solid #216442;outline-offset:3px}.permission-default{border:0;padding:0;margin:38px 0 28px;min-width:0}.permission-default legend{font-size:16px;font-weight:650;padding:0}.permission-default .help{font-size:14px;margin:8px 0 16px}.default-options{display:flex;border:1px solid #bccdc0;border-radius:6px;overflow:hidden;background:white}.default-options label{position:relative;flex:1;text-align:center;cursor:pointer}.default-options label+label{border-left:1px solid #bccdc0}.default-options input{position:absolute;opacity:0;width:1px;height:1px}.default-options span{display:flex;align-items:center;justify-content:center;min-height:44px;padding:8px;font-size:14px;height:100%}.default-options input:checked+span{background:#216442;color:white}.default-options input:focus-visible+span{outline:2px solid #172b26;outline-offset:-4px}.default-warning{color:#9c3724}.permissions .note{margin:24px 0}.exceptions-card{border-radius:7px;padding:22px;margin:24px 0}.exceptions-heading{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:22px}.exceptions-heading h2{margin:6px 0 0;font-size:18px}.refresh-tools{text-align:right}.refresh-tools button{padding:7px 12px;font-size:13px}.refresh-tools .help{margin:6px 0 0;font-size:12px}.exception-search{display:flex;gap:12px;margin-bottom:16px}.exception-search input{flex:1;min-width:0;font-size:14px}.exception-search button{white-space:nowrap;font-size:14px}.policy-columns,.policy-row{display:grid;grid-template-columns:minmax(0,1fr) 210px 32px;gap:14px;align-items:center}.policy-columns{background:#f5f7f3;padding:10px 8px;border-block:1px solid #e7ebe5;font-size:12px}.policy-row{padding:12px 8px;border-bottom:1px solid #e7ebe5}.policy-row summary{overflow-wrap:anywhere;font-size:14px;cursor:pointer}.policy-row details p{font-size:13px;line-height:1.5;overflow-wrap:anywhere}.policy-row select{font-size:13px;padding:9px 10px}.policy-row pre{padding:12px}.remove-exception{padding:6px;border:0;background:transparent;line-height:1;display:flex;justify-content:center}.remove-exception svg{width:17px;height:17px}.tool-select{display:none}.permissions input[type=checkbox]{width:16px;height:16px;margin:0;accent-color:#216442}.bulk-mode .policy-columns,.bulk-mode .policy-row{grid-template-columns:20px minmax(0,1fr) 210px 32px}.bulk-mode .tool-select{display:block}.bulk-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:16px 0;font-size:13px}.bulk-actions button{font-size:12px;padding:7px 10px}.bulk-actions span{margin-right:auto}.tool-navigation{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin-top:18px;font-size:13px}.text-button{border:0;padding:0;background:transparent;color:#226a4d;text-decoration:underline;font-size:13px}.tool-navigation .help{margin:0;margin-right:auto;font-size:12px}.policy-footer .help{font-size:12px}.policy-footer .actions{margin-top:28px}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}[hidden]{display:none!important}@media(max-width:600px){.connection-heading{align-items:flex-start;flex-direction:column;gap:12px}.auth-details{max-width:100%}.exceptions-card{padding:16px}.policy-columns,.policy-row{grid-template-columns:minmax(0,1fr) 32px;gap:10px}.policy-columns .permission-column{display:none}.policy-row details{grid-column:1}.policy-row .policy-choice{grid-column:1;grid-row:2}.policy-row .remove-exception{grid-column:2;grid-row:2}.bulk-mode .policy-columns,.bulk-mode .policy-row{grid-template-columns:20px minmax(0,1fr) 32px}.bulk-mode .policy-row details,.bulk-mode .policy-row .policy-choice{grid-column:2}.bulk-mode .policy-row .remove-exception{grid-column:3}.exception-search{flex-wrap:wrap}.exception-search input{flex-basis:100%}.default-options span{font-size:12px}.exceptions-heading{gap:8px}.refresh-tools{max-width:55%}}
</style></head><body><header><a href="/">mcp-gateway</a><small>Single-owner preview{{if not .Operation}} · {{.Owner}}{{end}}</small><form method="post" action="/logout"><button>Sign out</button></form></header><main>
{{if .AddConnection}}
<div class="setup"><a href="/">← Connections</a><h1>Add MCP</h1><p class="sub">Connect a remote server, then choose which tools agents can use.</p>
{{if .Error}}<p class="error" role="alert">{{.Error}}</p>{{end}}
<form method="post" action="/connections" autocomplete="off"><div class="card">
<div class="field"><label for="connection-id">Connection name</label><input id="connection-id" name="id" value="{{.Values.id}}" placeholder="github" pattern="[a-zA-Z0-9_-]{1,60}" maxlength="60" required><small>Used in tool IDs, such as github.create_issue. Letters, numbers, dashes and underscores.</small></div>
<div class="field"><label for="connection-url">MCP server URL</label><input id="connection-url" type="url" name="url" value="{{.Values.url}}" placeholder="https://mcp.example.com/mcp" maxlength="2048" required><small>Remote Streamable HTTP, public HTTPS only. Local command-based servers are not supported.</small></div>
<div class="field"><label for="connection-account">Account label <small>(optional)</small></label><input id="connection-account" name="account" value="{{.Values.account}}" maxlength="200" placeholder="Personal account"><small>A label for approval pages, not a verified account identity.</small></div>
<div class="field"><label for="connection-auth">Authentication</label><select id="connection-auth" name="auth"><option value="oauth" {{if eq .Values.auth "oauth"}}selected{{end}}>OAuth — sign in with the provider</option><option value="bearer" {{if eq .Values.auth "bearer"}}selected{{end}}>Bearer token</option><option value="none" {{if eq .Values.auth "none"}}selected{{end}}>None — public server</option></select></div>
<div class="bearer-fields field"><label for="connection-token">Bearer token</label><input id="connection-token" name="token" type="password" autocomplete="new-password"><small>Stored encrypted. Never shown again.</small></div>
<div class="oauth-fields"><p class="help">We discover OAuth settings and try to register a client. You’ll review the authorization server and scopes before signing in.</p><details><summary>Use an existing OAuth client</summary><div class="field"><label for="client-id">Client ID</label><input id="client-id" name="client_id" value="{{.Values.client_id}}" maxlength="1024"></div><div class="field"><label for="client-secret">Client secret <small>(if required)</small></label><input id="client-secret" name="client_secret" type="password" autocomplete="new-password"></div><p class="help endpoint">Register this callback, replacing CONNECTION-NAME with the name above:<br><code>{{.BaseURL}}/connections/CONNECTION-NAME/callback</code></p></details></div>
</div><p class="note">No tools are enabled when you add a server. Adding a connection or saving policies cancels queued requests; running calls must finish first.</p><div class="actions"><button class="primary">Add server</button><a class="button" href="/">Cancel</a></div></form></div>
{{else if .PolicyProposal}}
<div class="permissions"><a href="/">← Connections</a><h1>Review policy proposal</h1>
<p class="note">An agent proposed these changes. Nothing has been applied. Only you can apply or discard this entire batch. Tool names are not safety classifications.</p>
{{if .Proposal.Identity.UserID}}<p>Verified Amp user: <code>{{.Proposal.Identity.UserID}}</code><br>Verified thread: <a href="https://ampcode.com/threads/{{.Proposal.Identity.ThreadID}}">{{.Proposal.Identity.ThreadID}}</a></p>{{else}}<p>Authenticated bearer agent. No verified Amp user or thread identity.</p>{{end}}
<p class="help">Expires {{.Proposal.Expires.UTC.Format "15:04:05 UTC"}}. Any catalogue change invalidates this proposal. A restart also discards it.</p>
{{range .Connections}}<section class="card"><h2>{{.ID}}</h2><p>Connection default: <strong>{{.Before}} → {{.After}}</strong></p>
<p class="help">All saved tools shown below. Unspecified exceptions are preserved. “Use default” follows the connection default, including future tools.</p>
<div class="scroll"><table><thead><tr><th>Tool</th><th>Exception before → after</th><th>Effective before → after</th></tr></thead><tbody>
{{range .Rows}}<tr><td><code>{{.ID}}</code></td><td>{{.Before}} → {{.After}}</td><td><strong>{{.BeforeEffective}} → {{.AfterEffective}}</strong>{{if and (eq .Before .After) (eq .BeforeEffective .AfterEffective)}} <small>(unchanged)</small>{{end}}</td></tr>{{end}}
</tbody></table></div></section>{{end}}
<p class="help">Applying cancels queued requests. Running calls must finish first. This applies the stored proposal, not editable form values.</p>
<div class="actions"><form method="post" action="/policy-proposals/{{.Ticket}}/apply"><button class="primary">Apply proposed changes</button></form><form method="post" action="/policy-proposals/{{.Ticket}}/discard"><button>Discard proposal</button></form></div></div>
{{else if .ToolReview}}
<div class="permissions"><a href="/">← Connections</a>
<div class="connection-heading"><h1>{{.Connection.ID}}</h1>
{{if .Connection.OAuth}}<details class="auth-details" {{if ne .Connection.AuthStatus "Connected"}}open{{end}}><summary class="auth-status {{if ne .Connection.AuthStatus "Connected"}}pending{{end}}">OAuth · <span>{{.Connection.AuthStatus}}</span></summary>
<div role="status">{{if eq .Connection.AuthStatus "Connected"}}<p class="help">OAuth credentials saved. Fetch tools to check access with the provider.</p>
{{else if eq .Connection.AuthStatus "Reconnect required"}}<p class="help">The saved token has expired and cannot be refreshed. Reconnect to continue.</p>
{{else if eq .Connection.AuthStatus "Status unavailable"}}<p class="help">Could not read saved credentials. Try again before reconnecting.</p>
{{else}}<p class="help">Connect your provider account before fetching tools.</p>{{end}}</div>
<p class="help endpoint">Authorization server: {{.Connection.AuthURL}}</p><p class="help">Requested scopes: <code>{{.Connection.Scopes}}</code></p><form method="post" action="/connections/{{.Connection.ID}}/connect"><button>{{if eq .Connection.AuthStatus "Not connected"}}Connect OAuth{{else}}Reconnect OAuth{{end}}</button></form></details>{{end}}</div>
<p class="sub endpoint">{{.Connection.URL}}</p>
{{if .Error}}<p class="error" role="alert">{{.Error}}</p>{{end}}{{if .Saved}}<p class="success" role="status">Policies saved. Enabled tools are available to agents now.</p>{{end}}
<form id="refresh-tools" method="post" action="/connections/{{.Connection.ID}}/discover"></form>
{{if .Ticket}}
<form id="policies" method="post" action="/connections/{{.Connection.ID}}/tools"><input type="hidden" name="ticket" value="{{.Ticket}}">
<fieldset class="permission-default"><legend>Default permission for tools</legend><p class="help">Applies to tools without an exception, including new tools when you save a refresh.</p>
<div class="default-options"><label><input type="radio" name="default_policy" value="deny" {{if eq .Draft.Default "deny"}}checked{{end}}><span>Block</span></label><label><input type="radio" name="default_policy" value="require_approval" {{if eq .Draft.Default "require_approval"}}checked{{end}}><span>Require approval</span></label><label><input type="radio" name="default_policy" value="allow" {{if eq .Draft.Default "allow"}}checked{{end}}><span>Allow</span></label></div>
<p id="default-warning" class="default-warning" {{if ne .Draft.Default "allow"}}hidden{{end}}>Allow permits calls without approval, including newly discovered tools after saving. Tool names and read-only hints are not a safety guarantee.</p></fieldset>
<p class="note">Changed allowed tools require approval again. Blocked tools stay blocked.</p>
{{if .Draft.Removed}}<details><summary>Removed tools</summary><ul>{{range .Draft.Removed}}<li><code>{{.}}</code></li>{{end}}</ul></details>{{end}}
<div id="exceptions-card" class="card exceptions-card"><div class="exceptions-heading"><h2 id="tools-heading">Tools</h2><div class="refresh-tools"><button type="submit" formaction="/connections/{{.Connection.ID}}/discover">Refresh tools</button>{{if or .Draft.Changes .Draft.Removed}}<p class="help">{{.Added}} new · {{.Changed}} changed · {{len .Draft.Removed}} removed<br>Preview only · save to apply</p>{{end}}</div></div>
<div class="exception-search" id="exception-search" hidden><label class="visually-hidden" for="tool-search">Search tools</label><input type="search" id="tool-search" placeholder="Search tools…"><button type="button" id="add-exception">Add exception</button></div>
<div id="bulk-actions" class="bulk-actions" hidden><span id="selection-count">0 selected</span><button type="button" data-policy="allow">Allow</button><button type="button" data-policy="require_approval">Require approval</button><button type="button" data-policy="deny" class="danger">Block</button><button type="button" data-policy="inherit">Use default</button><button type="button" class="text-button" id="clear-selection">Clear</button></div>
<div class="policy-columns"><input id="select-visible" class="tool-select" type="checkbox" aria-label="Select visible tools"><span>Tool</span><span class="permission-column">Permission</span><span></span></div>
{{range $i,$row := .Rows}}<div class="policy-row" data-change="{{$row.Change}}"><input type="checkbox" class="tool-select" aria-label="Select {{$row.Tool.ID}}"><details><summary>{{$row.Tool.Name}} {{if $row.Change}}<span class="badge">{{$row.Change}}</span>{{end}}</summary><p><code>{{$row.Tool.ID}}</code></p><p>{{$row.Tool.Description}}</p><p class="help">Provider description · not a safety guarantee</p><pre>{{$row.Schema}}</pre></details><div class="policy-choice"><label class="visually-hidden" for="policy-{{$i}}">Permission for {{$row.Tool.Name}}</label><select class="tool-policy" id="policy-{{$i}}" name="policy_{{$i}}"><option value="inherit" {{if eq $row.Tool.Policy ""}}selected{{end}}>Use connection default</option><option value="deny" {{if eq $row.Tool.Policy "deny"}}selected{{end}}>Block</option><option value="require_approval" {{if eq $row.Tool.Policy "require_approval"}}selected{{end}}>Require approval</option><option value="allow" {{if eq $row.Tool.Policy "allow"}}selected{{end}}>Allow</option></select></div><button type="button" class="remove-exception" aria-label="Remove exception for {{$row.Tool.Name}}" title="Use connection default" hidden><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7m4-7v7"/></svg></button></div>{{end}}
<p id="no-matches" class="help" hidden></p>
<div id="tool-navigation" class="tool-navigation" hidden><p id="tool-count" class="help"></p><button type="button" class="text-button" data-view="exceptions">Exceptions</button><button type="button" class="text-button" data-view="all">All tools</button><button type="button" class="text-button" data-view="changes">New or changed</button></div>
</div><div class="policy-footer"><div class="actions"><button class="primary">Save changes</button><a class="button" href="/connections/{{.Connection.ID}}/tools">Discard</a></div><p id="edit-status" role="status" class="help"></p><p class="help">Nothing changes until you save. Saving cancels queued requests; running calls must finish first. Edits expire in ten minutes.</p></div></form>
<script>
(() => {
 const form = document.getElementById('policies');
 const rows = Array.from(form.querySelectorAll('.policy-row'));
 const search = document.getElementById('tool-search');
 const card = document.getElementById('exceptions-card');
 const selectAll = document.getElementById('select-visible');
 const status = document.getElementById('edit-status');
 const defaults = form.querySelectorAll('input[name="default_policy"]');
 let view = 'exceptions';
 let dirty = false;
 function filter() {
  const query = search.value.toLowerCase().trim();
  const activeView = query ? 'all' : view;
  const defaultPolicy = form.querySelector('input[name="default_policy"]:checked').value;
  const defaultLabel = { deny: 'Block', require_approval: 'Require approval', allow: 'Allow' }[defaultPolicy];
  for (const row of rows) {
   const policy = row.querySelector('.tool-policy');
   policy.querySelector('option[value="inherit"]').textContent = 'Default: ' + defaultLabel;
   const exception = policy.value !== 'inherit';
   row.hidden = !row.querySelector('details').textContent.toLowerCase().includes(query) || (activeView === 'exceptions' && !exception) || (activeView === 'changes' && !row.dataset.change);
   row.querySelector('.remove-exception').hidden = !exception;
   if (row.hidden) row.querySelector('.tool-select').checked = false;
  }
  const visible = rows.filter(row => !row.hidden);
  const selected = visible.filter(row => row.querySelector('.tool-select').checked).length;
  const exceptions = rows.filter(row => row.querySelector('.tool-policy').value !== 'inherit').length;
  selectAll.checked = visible.length > 0 && selected === visible.length;
  selectAll.indeterminate = selected > 0 && selected < visible.length;
  card.classList.toggle('bulk-mode', activeView !== 'exceptions');
  document.getElementById('tools-heading').textContent = query ? 'Search results (' + visible.length + ')' : view === 'exceptions' ? 'Exceptions (' + exceptions + ')' : view === 'all' ? 'All tools (' + rows.length + ')' : 'New or changed tools';
  document.getElementById('add-exception').hidden = activeView !== 'exceptions';
  document.getElementById('bulk-actions').hidden = activeView === 'exceptions';
  document.getElementById('selection-count').textContent = selected + ' selected';
  document.querySelectorAll('[data-policy]').forEach(button => { button.disabled = selected === 0; });
  document.querySelectorAll('[data-view]').forEach(button => { button.hidden = !query && button.dataset.view === view; });
  document.getElementById('tool-count').textContent = activeView === 'exceptions' ? (rows.length - exceptions) + ' tools use the default' : visible.length + ' of ' + rows.length + ' tools shown';
  document.getElementById('no-matches').hidden = visible.length !== 0;
  document.getElementById('no-matches').textContent = rows.length === 0 ? 'No tools yet. Refresh tools to discover what this server offers.' : query ? 'No matching tools.' : view === 'exceptions' ? 'No exceptions. All tools use the connection default.' : 'No new or changed tools in this review.';
 }
 function edited() { dirty = true; status.textContent = 'Unsaved changes'; filter(); }
 function show(viewName) {
  view = viewName; search.value = '';
  rows.forEach(row => { row.querySelector('.tool-select').checked = false; });
  filter();
  search.focus();
 }
 document.getElementById('exception-search').hidden = false;
 document.getElementById('tool-navigation').hidden = false;
 search.addEventListener('input', filter);
 document.querySelectorAll('[data-view]').forEach(button => button.addEventListener('click', () => show(button.dataset.view)));
 document.getElementById('add-exception').addEventListener('click', () => { show('all'); search.focus(); status.textContent = 'Choose a tool permission to add an exception. Changes are saved together.'; });
 selectAll.addEventListener('change', () => { rows.filter(row => !row.hidden).forEach(row => { row.querySelector('.tool-select').checked = selectAll.checked; }); filter(); });
 document.getElementById('clear-selection').addEventListener('click', () => { rows.forEach(row => { row.querySelector('.tool-select').checked = false; }); filter(); });
 rows.forEach(row => {
  row.querySelector('.tool-select').addEventListener('change', filter);
  row.querySelector('.tool-policy').addEventListener('change', edited);
  row.querySelector('.remove-exception').addEventListener('click', () => {
   row.querySelector('.tool-policy').value = 'inherit'; edited();
   (row.hidden ? document.getElementById('add-exception') : row.querySelector('.tool-policy')).focus();
  });
 });
 document.querySelectorAll('[data-policy]').forEach(button => button.addEventListener('click', () => {
  const selected = rows.filter(row => !row.hidden && row.querySelector('.tool-select').checked);
  selected.forEach(row => { row.querySelector('.tool-policy').value = button.dataset.policy; });
  edited(); status.textContent = selected.length + ' tools updated. Save changes to apply.';
 }));
 defaults.forEach(input => input.addEventListener('change', () => { document.getElementById('default-warning').hidden = input.value !== 'allow'; edited(); }));
 form.addEventListener('submit', () => { dirty = false; });
 window.addEventListener('beforeunload', event => { if (dirty) { event.preventDefault(); event.returnValue = ''; } });
 filter();
})();
</script>
{{else}}<p class="help">Open <a href="/connections/{{.Connection.ID}}/tools">saved permissions</a> to edit without fetching the provider.</p><button form="refresh-tools">Refresh tools</button>{{end}}</div>
{{else}}
{{if .Operation}}{{with .Operation}}
<section class="operation"><style>.operation{max-width:860px;margin:auto;overflow-wrap:anywhere}.operation h1{text-transform:capitalize}.operation .heading h1{margin-top:18px}.operation h2{margin-top:0}.operation summary{font-weight:600}.operation details.card{padding:18px 24px}.operation pre{line-height:1.65;font-size:13px}.operation .attribution{font-size:14px;margin:22px 0}.operation .result pre{background:#f7f9f5;border:1px solid #e7ebe5}.operation .result details{margin-top:24px}.operation .result summary{font-size:13px;color:#586b62}</style>
<a href="/">← All activity</a><div class="heading"><h1>{{$.Title}}</h1><span class="badge {{.Status}}" role="status">{{.Status}}</span></div>
<p class="sub"><code>{{.Tool}}</code> · {{.Account}} <small>(configured account label)</small></p>
{{if .AmpThreadID}}<p class="attribution"><a href="https://ampcode.com/threads/{{.AmpThreadID}}">Open Amp thread ↗</a> · Amp identity verified. Not human approval or model attestation.</p>{{end}}
{{if eq .Status "pending"}}<div class="card"><h2>Review this request</h2><p>Account: <strong>{{.Account}}</strong> (configured label) · Connection: <code>{{.Connection}}</code></p><h3>Exact arguments</h3><pre>{{$.Arguments}}</pre><p class="note">Approve only if the account, tool and arguments are correct. Approval expires 10 minutes after submission and authorises this stored request once. This is not an effect preview.</p><div class="actions"><form method="post" action="/operations/{{.ID}}/approve"><button class="primary">Approve once</button></form><form method="post" action="/operations/{{.ID}}/deny"><button class="danger">Deny</button></form></div></div>
{{else if or (eq .Status "ready") (eq .Status "running")}}<p class="sub">Refresh to see the latest execution status.</p><a class="button" href="/operations/{{.ID}}">Refresh status</a>
{{else if eq .Status "unknown"}}<p class="note">The outcome is unknown. Check the upstream service before trying again. This call will not be retried automatically.</p>
{{else if eq .Status "denied"}}<p class="sub">This request was denied and was not executed.</p>
{{else if eq .Status "expired"}}<p class="sub">This request expired and was not executed.</p>{{end}}
{{if .Result}}<div class="card result"><h2>{{if eq .Status "failed"}}Error response{{else}}Result{{end}}</h2>{{range $.ResultBlocks}}<pre>{{.}}</pre>{{end}}<details><summary>{{if eq .Status "unknown"}}Stored response{{else}}Raw MCP response{{end}}</summary><pre>{{$.RawResult}}</pre></details></div>{{end}}
<details class="card"><summary>Request details</summary><dl><dt>Request ID</dt><dd><code>{{.ID}}</code></dd><dt>Tool</dt><dd><code>{{.Tool}}</code></dd><dt>Connection</dt><dd>{{.Connection}}</dd></dl><h3>Exact arguments</h3><pre>{{$.Arguments}}</pre></details>
<details class="card"><summary>Identity &amp; audit</summary><dl><dt>On behalf of</dt><dd>{{.Subject}}</dd>{{if .AmpUserID}}<dt>Amp user</dt><dd><code>{{.AmpUserID}}</code> (verified)</dd>{{end}}<dt>Upstream account</dt><dd>{{.Account}} <small>(configured label, not verified identity)</small></dd><dt>Calling model</dt><dd>{{if .Model}}{{.Model}} — client-reported, unverified{{else}}Unknown — not supplied by client{{end}}</dd><dt>Request digest</dt><dd><code>{{.Digest}}</code></dd></dl></details></section>{{end}}
{{else}}<h1>Connections and activity</h1><p class="sub">Choose the tools agents can use. Review calls that need your approval.</p><div class="heading"><h2>Connections</h2><a class="button primary" href="/connections/new">Add MCP</a></div><div class="grid">{{range .Connections}}<div class="card"><strong>{{.ID}}</strong><p class="sub">{{.Account}}</p>
{{if .OAuth}}<div role="status" style="display:flex;align-items:center;flex-wrap:wrap;gap:8px"><span class="badge {{if eq .AuthStatus "Connected"}}succeeded{{else}}pending{{end}}">OAuth · {{.AuthStatus}}</span><form method="post" action="/connections/{{.ID}}/connect"><button>{{if eq .AuthStatus "Not connected"}}Connect{{else}}Reconnect{{end}}</button></form></div>
{{if eq .AuthStatus "Connected"}}<p class="help"><small>Credentials saved; provider access not verified.</small></p>{{else if eq .AuthStatus "Status unavailable"}}<p class="help"><small>Could not read saved credentials. Try again before reconnecting.</small></p>{{end}}{{end}}
<a class="button" href="/connections/{{.ID}}/tools">Manage tools</a></div>{{else}}<div class="card"><p>No MCP servers connected yet.</p><p class="sub">Add a server, connect credentials, then review its tools.</p></div>{{end}}</div><h2>Operations</h2><div class="card scroll">{{if .Operations}}<table><thead><tr><th>Request</th><th>Tool</th><th>Account</th><th>Status</th></tr></thead><tbody>{{range .Operations}}<tr><td><a href="/operations/{{.ID}}">{{.ID}}</a></td><td>{{.Tool}}</td><td>{{.Account}}</td><td><span class="badge {{.Status}}">{{.Status}}</span></td></tr>{{end}}</tbody></table>{{else}}<p class="sub">No operations yet. Connect an MCP client and use find_tools, then call_tools.</p>{{end}}</div><h2>Audit trail</h2><div class="card scroll"><table><thead><tr><th>Sequence</th><th>Operation</th><th>Transition</th><th>Actor</th></tr></thead><tbody>{{range .Events}}<tr><td>{{.Sequence}}</td><td><a href="/operations/{{.Operation}}">{{.Operation}}</a></td><td>{{.Kind}}</td><td>{{.Actor}}</td></tr>{{else}}<tr><td colspan="4">No events yet.</td></tr>{{end}}</tbody></table></div>{{end}}
{{end}}<footer>Local durable audit · encrypted payloads · not independently tamper-proof · no automatic write retries</footer></main></body></html>`))
